// n8n Code node — "Build MESA Emails" (Run Once for All Items)
// Fired by Simple HRIS once per MESA request a member files from Employee → MESA →
// Request (POST /api/mesa-requests): an opt-out, a disbursement or a return. Fans
// out ONE item per recipient, each carrying a ready-to-send HTML email saying a
// request is waiting in Accounting → MESA → Requests.
//
// WHO is mailed comes from the payload: the HRIS resolves it from Admin →
// Webhooks → "MESA Request → Notify Accounting" → Open automation (default
// carla@simple.biz + april@simple.biz). Subject and body are FIXED here — the
// caller only says who filed what kind of request and when, so this endpoint
// cannot become an arbitrary-content mailer.
//
// NO MONEY, NO REASON: the HRIS never sends the peso figure or why the member is
// asking (often medical). Do not add them here either — the recipient list is
// admin-editable. The reviewer reads both inside the HRIS.
//
// Payload (n8n may nest the POST body under `.body`):
//   {
//     event: 'mesa.requested', trigger: 'employee_mesa_request',
//     request: { id, request_type, request_label, employee_name, employee_email,
//                department, requested_at, requested_at_manila },
//     recipients: [ { email, name } ],
//     sent_by: 'system',
//     test: true            // Admin → Webhooks test run (goes to the admin only)
//   }

// --- OPTIONAL shared-secret gate ---
// Leave '' to accept any caller. To lock down: put a long random string here AND
// set HRIS env N8N_MESA_REQUEST_NOTIFY_SECRET to the same value (sent as the
// 'x-webhook-secret' header).
const REQUIRED_SECRET = '';

const HRIS_LINK = 'https://simple-hris.vercel.app/';
const LOGO = 'https://simple-hris.vercel.app/simple-logo.png';
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MAX = 300;
const LABELS = { opt_out: 'Opt-out', disbursement: 'Disbursement', return: 'Return' };

const root = (items[0] && items[0].json) || {};
const body = (root && typeof root.body === 'object' && root.body) ? root.body : root;
const headers = (root && typeof root.headers === 'object' && root.headers) ? root.headers : {};

const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.secret || '';
if (REQUIRED_SECRET && providedSecret !== REQUIRED_SECRET) {
  throw new Error('Unauthorized: missing or invalid webhook secret.');
}

if (body.event !== 'mesa.requested') {
  throw new Error('Not a MESA request event (got ' + JSON.stringify(body.event) + ').');
}

function esc(v) {
  if (v == null) return '';
  return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// --- recipients (from the HRIS; validated, deduped, capped) ---
const seen = {};
const recipients = [];
for (const r of (Array.isArray(body.recipients) ? body.recipients : [])) {
  const email = String((r && r.email) || '').trim().toLowerCase();
  if (!EMAIL_RE.test(email) || seen[email]) continue;
  seen[email] = true;
  recipients.push(email);
}
if (recipients.length === 0) throw new Error('No valid recipients in the payload.');
if (recipients.length > MAX) throw new Error('Too many recipients (' + recipients.length + ' > ' + MAX + ').');

// --- the request ---
const req = (body.request && typeof body.request === 'object') ? body.request : {};
const isTest = body.test === true;
const label = LABELS[req.request_type] || 'MESA';
const plainName = String(req.employee_name || '').trim() || String(req.employee_email || '').trim() || 'A member';
const name = esc(plainName);
const workEmail = esc(req.employee_email || '');
const dept = esc(String(req.department || '').trim());
const when = esc(req.requested_at_manila || req.requested_at || '');
const refId = esc(req.id || '');

const SUBJECT = (isTest ? '[TEST RUN] ' : '') + '🩺 New MESA ' + label.toLowerCase() + ' request — ' + plainName;

function detailRow(rowLabel, value) {
  if (!value) return '';
  return '<tr>' +
    '<td style="padding:8px 14px;font-size:12px;color:#71717a;white-space:nowrap;vertical-align:top;border-bottom:1px solid #f4f4f5">' + rowLabel + '</td>' +
    '<td style="padding:8px 14px;font-size:13px;color:#18181b;font-weight:bold;border-bottom:1px solid #f4f4f5">' + value + '</td>' +
  '</tr>';
}

function ctaButton() {
  return '' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 6px"><tr><td>' +
      '<!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="' + HRIS_LINK + '" style="height:48px;v-text-anchor:middle;width:300px;" arcsize="21%" strokecolor="#0d9488" fillcolor="#0d9488"><w:anchorlock/><center style="color:#ffffff;font-family:Arial,sans-serif;font-size:15px;font-weight:bold;">Open HRIS &rarr; Accounting &rarr; MESA</center></v:roundrect><![endif]-->' +
      '<!--[if !mso]><!-- --><a href="' + HRIS_LINK + '" style="display:inline-block;background:#0d9488;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;padding:14px 28px;border-radius:10px">Open HRIS &rarr; Accounting &rarr; MESA</a><!--<![endif]-->' +
    '</td></tr></table>';
}

function renderHtml() {
  const details =
    detailRow('Requested by', name + (workEmail ? ' &middot; <span style="font-weight:normal;color:#52525b">' + workEmail + '</span>' : '')) +
    detailRow('Request', esc(label)) +
    detailRow('Department', dept) +
    detailRow('Submitted on', when ? when + ' <span style="font-weight:normal;color:#71717a">(Manila)</span>' : '') +
    detailRow('Reference ID', refId ? '<span style="font-family:Consolas,Menlo,monospace;font-weight:normal">' + refId + '</span>' : '');
  const testBanner = isTest
    ? '<tr><td style="background:#fef3c7;border-bottom:1px solid #fde68a;padding:10px 26px;font-size:12px;color:#92400e;font-weight:bold">TEST RUN &mdash; sent from Admin &rarr; Webhooks to you only. No member filed this request.</td></tr>'
    : '';
  return '' +
    '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MESA request</title></head>' +
    '<body style="margin:0;background:#f4f4f5;padding:24px 12px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#18181b">' +
      '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;font-size:1px;line-height:1px">' + name + ' filed a MESA ' + esc(label.toLowerCase()) + ' request &mdash; it is waiting in Accounting &rarr; MESA &rarr; Requests.</div>' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5"><tr><td align="center">' +
        '<table role="presentation" width="520" cellpadding="0" cellspacing="0" style="width:100%;max-width:520px;background:#ffffff;border:1px solid #e4e4e7;border-radius:14px;overflow:hidden;box-shadow:0 6px 24px rgba(13,148,136,0.10)">' +
          testBanner +
          '<tr><td style="padding:18px 26px 12px"><img src="' + LOGO + '" alt="Simple" width="88" height="30" style="display:block;border:0;height:30px;width:88px"></td></tr>' +
          '<tr><td bgcolor="#0a0a0b" style="background:#0a0a0b;padding:22px 26px;border-bottom:4px solid #0d9488">' +
            '<span style="display:inline-block;background:#0d9488;color:#ffffff;font-size:11px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase;padding:5px 12px;border-radius:999px">MESA &middot; ' + esc(label) + '</span>' +
            '<div style="margin-top:14px;font-size:22px;line-height:1.3;color:#ffffff;font-weight:bold">A MESA request is waiting for review</div>' +
            '<div style="margin-top:6px;font-size:13px;color:#d4d4d8">A member just filed one from their dashboard.</div>' +
          '</td></tr>' +
          '<tr><td style="padding:22px 26px 4px">' +
            '<p style="margin:0 0 14px;font-size:15px;color:#18181b">Hi,</p>' +
            '<p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#3f3f46">A new <strong>MESA ' + esc(label.toLowerCase()) + ' request</strong> was just filed in the HRIS. Review it in <strong>Accounting &rarr; MESA &rarr; Requests</strong> &mdash; the details and the member&rsquo;s balance are there.</p>' +
            '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f0fdfa;border:1px solid #99f6e4;border-radius:10px;margin:0 0 18px;overflow:hidden">' + details + '</table>' +
            ctaButton() +
            '<p style="margin:10px 0 18px;font-size:12px;color:#71717a;word-break:break-all">Button not working? Copy and paste this link:<br><a href="' + HRIS_LINK + '" style="color:#0d9488">' + esc(HRIS_LINK) + '</a></p>' +
          '</td></tr>' +
          '<tr><td style="padding:16px 26px 20px;border-top:1px solid #f4f4f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="font-size:12px;color:#52525b;font-weight:bold">Simple &middot; Confidential</td><td align="right" style="font-size:11px;color:#71717a">Automated alert from Simple HRIS</td></tr></table></td></tr>' +
        '</table>' +
        '<div style="max-width:520px;margin:12px auto 0;font-size:11px;color:#71717a;text-align:center;line-height:1.5">You are receiving this because you are on the MESA request list in Admin &rarr; Webhooks.</div>' +
      '</td></tr></table>' +
    '</body></html>';
}

const html = renderHtml();
return recipients.map(function (email) {
  return { json: { to: email, subject: SUBJECT, html: html } };
});
